using System.Globalization;
using System.Text.RegularExpressions;
namespace Hix.Standalone;
public sealed class HixVersion : IComparable<HixVersion>, IEquatable<HixVersion> {
  private static readonly Regex Syntax = new("^(?:(?<product>[0-9]+)\\.)?(?<major>[0-9]+)\\.(?<minor>[0-9]+)\\.(?<patch>[0-9]+)(?:-(?<branch>[0-9A-Za-z][0-9A-Za-z-]*)(?:\\.(?<revision>[0-9]+))?)?$", RegexOptions.CultureInvariant);
  public int? Product { get; } public int Major { get; } public int Minor { get; } public int Patch { get; } public string Branch { get; } public int? Revision { get; }
  private HixVersion(int? product, int major, int minor, int patch, string branch, int? revision) => (Product, Major, Minor, Patch, Branch, Revision) = (product, major, minor, patch, branch, revision);
  public static HixVersion Parse(string text) => TryParse(text, out var version) ? version : throw new FormatException("Invalid Hix version '" + text + "'");
  public static bool TryParse(string text, out HixVersion version) { var match = Syntax.Match(text ?? ""); version = null; if (!match.Success) return false; int? Optional(string n) => match.Groups[n].Success ? int.Parse(match.Groups[n].Value, CultureInfo.InvariantCulture) : null; version = new(Optional("product"), int.Parse(match.Groups["major"].Value), int.Parse(match.Groups["minor"].Value), int.Parse(match.Groups["patch"].Value), match.Groups["branch"].Success ? match.Groups["branch"].Value : null, Optional("revision")); return true; }
  public int CompareTo(HixVersion other) { if (other == null) return 1; foreach (var value in new[] {(Product ?? 0).CompareTo(other.Product ?? 0), Major.CompareTo(other.Major), Minor.CompareTo(other.Minor), Patch.CompareTo(other.Patch)}) if (value != 0) return value; if (Branch == null || other.Branch == null) return Branch == other.Branch ? 0 : Branch == null ? 1 : -1; var branch = string.CompareOrdinal(Branch, other.Branch); return branch != 0 ? branch : (Revision ?? 0).CompareTo(other.Revision ?? 0); }
  public bool Equals(HixVersion other) => other != null && CompareTo(other) == 0; public override bool Equals(object obj) => obj is HixVersion other && Equals(other); public override int GetHashCode() => ToString().GetHashCode();
  public override string ToString() => (Product is null ? "" : Product + ".") + $"{Major}.{Minor}.{Patch}" + (Branch is null ? "" : "-" + Branch + (Revision is null ? "" : "." + Revision));
}
public sealed class HixVersionConstraint {
  private readonly Func<HixVersion, bool> matches; private HixVersionConstraint(string text, Func<HixVersion, bool> match) => (Text, matches) = (text, match); public string Text { get; } public bool Matches(HixVersion version) => version != null && matches(version);
  public static HixVersionConstraint Parse(string text) { if (string.IsNullOrWhiteSpace(text)) throw new FormatException("Version constraint is empty"); var alternatives = text.Split(new[] {"||"}, StringSplitOptions.None).Select(Alternative).ToArray(); return new(text, v => alternatives.Any(x => x(v))); }
  private static Func<HixVersion, bool> Alternative(string source) { source = source.Trim(); var hyphen = Regex.Match(source, "^(.+?)\\s+-\\s+(.+)$"); if (hyphen.Success) { var low = HixVersion.Parse(hyphen.Groups[1].Value); var high = HixVersion.Parse(hyphen.Groups[2].Value); return v => v.CompareTo(low) >= 0 && v.CompareTo(high) <= 0; } var terms = source.Split((char[])null, StringSplitOptions.RemoveEmptyEntries).Select(Term).ToArray(); return v => terms.All(x => x(v)); }
  private static Func<HixVersion, bool> Term(string term) { if (term is "*" or "x" or "X") return _ => true; if (term.StartsWith("^")) return Range(term.Substring(1), true); if (term.StartsWith("~")) return Range(term.Substring(1), false); foreach (var op in new[] {">=", "<=", ">", "<", "="}) if (term.StartsWith(op)) { var expected = HixVersion.Parse(term.Substring(op.Length)); return v => op switch {">=" => v.CompareTo(expected) >= 0, "<=" => v.CompareTo(expected) <= 0, ">" => v.CompareTo(expected) > 0, "<" => v.CompareTo(expected) < 0, _ => v.CompareTo(expected) == 0}; } if (term.Contains('*') || Regex.IsMatch(term, "(^|\\.)(x|X)($|\\.)")) { var parts = term.Split('.'); return v => Part(parts, 0, v.Product ?? v.Major) && Part(parts, 1, v.Product.HasValue ? v.Major : v.Minor) && Part(parts, 2, v.Product.HasValue ? v.Minor : v.Patch) && (parts.Length < 4 || Part(parts, 3, v.Patch)); } var exact = HixVersion.Parse(term); return v => v.CompareTo(exact) == 0; }
  private static bool Part(string[] parts, int index, int value) => index >= parts.Length || parts[index] is "*" or "x" or "X" || int.TryParse(parts[index], out var expected) && value == expected;
  private static Func<HixVersion, bool> Range(string value, bool caret) { var low = HixVersion.Parse(value); var high = HixVersion.Parse(caret ? low.Major > 0 ? $"{low.Major + 1}.0.0" : low.Minor > 0 ? $"0.{low.Minor + 1}.0" : $"0.0.{low.Patch + 1}" : $"{low.Major}.{low.Minor + 1}.0"); return v => v.CompareTo(low) >= 0 && v.CompareTo(high) < 0; }
}
